<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $interests = sd_member_interests( $args['user']->ID ); if ( empty( $interests ) ) { return; } ?><section class="sd-profile-section"><h2><?php esc_html_e( 'Interests', 'social-discovery' ); ?></h2><div class="sd-profile-interest-list"><?php foreach ( $interests as $interest ) : ?><span class="sd-pill"><?php echo esc_html( $interest ); ?></span><?php endforeach; ?></div></section>
